JOIN (
    SELECT 'Palmito' common_name, 'Chamaerops humilis' scientific_name, 'flora' kingdom, 'Palmera' family, 'Sabinar y matorral termomediterráneo' primary_habitat, 'Interés especial' conservation_status, 'Única palmera autóctona de Europa continental, elemento termófilo característico del sabinar de Cabo Cope, donde acompaña a la sabina negral en la asociación Chamaeropo humilis-Juniperetum phoeniceae.' description, 'Hojas en abanico con peciolo espinoso; Porte arbustivo en mata; Elemento termófilo del sabinar' identification_tips, 'Todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chamaerops_humilis_001.JPG' image_url, 37.4998 latitude, -1.4378 longitude, 3 rarity_score, FALSE is_featured, 'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003)' source, 'Tracheophyta' taxon_phylum, 'Liliopsida' taxon_class, 'Arecales' taxon_order, 'Arecaceae' taxon_family, 'Chamaerops' taxon_genus, 'NE' iucn_global, 'No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)' spain_status, 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial' murcia_status, 'Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; el hábitat se apoya en la asociación fitosociológica citada por las fuentes oficiales del parque. Coordenadas representativas, pendientes de precisar en campo.' review_note
