-- ================================================================================================
-- Ampliación (2026-07-13): flora característica de los hábitats que quedaban vacíos o casi vacíos
-- (2110, 2230, 6110*, 3250) y asignación de la especie huérfana Senecio flavus. Solo especies
-- diagnósticas/características de cada HIC (Bases ecológicas VVAA/MMARM 2009 + fichas Red Natura
-- 2000 / Murcianatural CARM) con presencia confirmada en la Región de Murcia; llevan review_note
-- porque su presencia en el parque se infiere del hábitat cartografiado (no son registros directos).
-- ================================================================================================
INSERT INTO species (park_id, common_name, scientific_name, kingdom, family, primary_habitat, conservation_status,
    description, identification_tips, seasonality, image_url, latitude, longitude, rarity_score, is_featured, source,
    taxon_phylum, taxon_class, taxon_order, taxon_family, taxon_genus, iucn_global, spain_status, murcia_status, review_note)
SELECT p.id, s.common_name, s.scientific_name, s.kingdom, s.family, s.primary_habitat, s.conservation_status,
    s.description, s.identification_tips, s.seasonality, s.image_url, s.latitude, s.longitude, s.rarity_score, s.is_featured, s.source,
    s.taxon_phylum, s.taxon_class, s.taxon_order, s.taxon_family, s.taxon_genus, s.iucn_global, s.spain_status, s.murcia_status, s.review_note
FROM parks p
JOIN (
    -- ===== 2110 · Dunas móviles embrionarias =====================================================
    SELECT 'Grama de mar' common_name, 'Elymus farctus' scientific_name, 'flora' kingdom, 'Gramínea psammófila' family, 'Dunas móviles embrionarias' primary_habitat, 'Preocupación menor' conservation_status, 'Gramínea rizomatosa y glauca que entrelaza la arena con sus largos rizomas y levanta las primeras dunas embrionarias; especie dominante de este hábitat en el Mediterráneo.' description, 'Rizomas largos que traban la arena; Hojas glaucas y rígidas; Espiga que se fragmenta al madurar' identification_tips, 'Primavera y verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Elymus_farctus_kz14.jpg' image_url, 37.46665 latitude, -1.47360 longitude, 2 rarity_score, FALSE is_featured, 'Especie dominante/característica del hábitat de interés comunitario 2110 (Dunas móviles embrionarias) según las Bases ecológicas preliminares para la conservación de los tipos de hábitat de interés comunitario en España (VVAA, Ministerio de Medio Ambiente, Medio Rural y Marino, 2009) y la ficha del hábitat (Murcianatural, CARM); presencia en el litoral de la Región de Murcia confirmada en la flora regional. Sinónimos: Elytrigia juncea, Thinopyrum junceum.' source, 'Tracheophyta' taxon_phylum, 'Liliopsida' taxon_class, 'Poales' taxon_order, 'Poaceae' taxon_family, 'Elymus' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común de amplia distribución litoral)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia (Decreto 50/2003); citada como especie característica de este hábitat en el litoral murciano' murcia_status, 'Añadida como especie característica del hábitat 2110, documentada en el litoral de la Región de Murcia. Su presencia concreta en el parque se infiere del hábitat cartografiado y queda pendiente de confirmación en campo.' review_note
    UNION ALL
