-- Relación especie <-> hábitat de la tanda 1 (una fila por vínculo; algunas especies en 2 hábitats).
INSERT IGNORE INTO species_habitats (species_id, habitat_id)
SELECT sp.id, h.id
FROM (
    SELECT 'Arthrocnemum macrostachyum' scientific_name, 'matorral-halofilo' habitat_slug
    UNION ALL SELECT 'Sarcocornia fruticosa', 'matorral-halofilo'
    UNION ALL SELECT 'Halimione portulacoides', 'matorral-halofilo'
    UNION ALL SELECT 'Suaeda vera', 'matorral-halofilo'
    UNION ALL SELECT 'Suaeda vera', 'matorral-halonitrofilo'
    UNION ALL SELECT 'Atriplex halimus', 'matorral-halonitrofilo'
    UNION ALL SELECT 'Salsola vermiculata', 'matorral-halonitrofilo'
    UNION ALL SELECT 'Limonium delicatulum', 'estepas-salinas-albardinal'
    UNION ALL SELECT 'Frankenia corymbosa', 'estepas-salinas-albardinal'
    UNION ALL SELECT 'Crithmum maritimum', 'acantilados'
    UNION ALL SELECT 'Cakile maritima', 'veg-anual-desechos-marinos'
    UNION ALL SELECT 'Salsola kali', 'veg-anual-desechos-marinos'
    UNION ALL SELECT 'Beta maritima', 'veg-anual-desechos-marinos'
    UNION ALL SELECT 'Brachypodium retusum', 'subestepa-thero-brachypodietea'
    UNION ALL SELECT 'Brachypodium retusum', 'matorral-semiarido'
    UNION ALL SELECT 'Stipa capensis', 'subestepa-thero-brachypodietea'
    UNION ALL SELECT 'Stipa capensis', 'matorral-semiarido'
    UNION ALL SELECT 'Hyparrhenia hirta', 'subestepa-thero-brachypodietea'
    UNION ALL SELECT 'Plantago albicans', 'subestepa-thero-brachypodietea'
    UNION ALL SELECT 'Asphodelus fistulosus', 'subestepa-thero-brachypodietea'
    UNION ALL SELECT 'Nerium oleander', 'galeria-ribera'
    UNION ALL SELECT 'Saccharum ravennae', 'galeria-ribera'
) rel
JOIN species sp ON sp.scientific_name = rel.scientific_name
JOIN habitats h ON h.slug = rel.habitat_slug
JOIN parks p ON p.id = sp.park_id AND p.id = h.park_id
WHERE p.slug = 'cabo-cope-puntas-calnegre';


-- ===== Tanda 2 de ampliación de flora (matorral semiárido y compañeras) — fichas mínimas =====

INSERT INTO species (park_id, common_name, scientific_name, kingdom, family, primary_habitat, conservation_status,
    description, identification_tips, seasonality, image_url, latitude, longitude, rarity_score, is_featured, source,
    taxon_phylum, taxon_class, taxon_order, taxon_family, taxon_genus, iucn_global, spain_status, murcia_status, review_note)
SELECT p.id, s.common_name, s.scientific_name, s.kingdom, s.family, s.primary_habitat, s.conservation_status,
    s.description, s.identification_tips, s.seasonality, s.image_url, s.latitude, s.longitude, s.rarity_score, s.is_featured, s.source,
    s.taxon_phylum, s.taxon_class, s.taxon_order, s.taxon_family, s.taxon_genus, s.iucn_global, s.spain_status, s.murcia_status, s.review_note
FROM parks p
JOIN (
    SELECT 'Esparto' common_name, 'Stipa tenacissima' scientific_name, 'flora' kingdom, 'Gramínea vivaz esteparia' family, 'Matorral termomediterráneo semiárido' primary_habitat, 'No amenazada' conservation_status, 'Gramínea vivaz que forma los espartales o atochares, pastizal-matorral dominante en las laderas secas del sureste; su fibra se ha aprovechado tradicionalmente. Estructura buena parte del paisaje semiárido del parque.' description, NULL identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stipa_tenacissima.jpg' image_url, 37.50130 latitude, -1.44960 longitude, 1 rarity_score, FALSE is_featured, 'Especie estructural del matorral y pastizal semiárido (hábitat 5330 y espartales termomediterráneos) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; los espartales de la Marina de Cope se citan expresamente en la flora del parque (regmurcia.com). Sinónimo: Macrochloa tenacissima. Ficha básica (mínima), pendiente de ampliar.' source, 'Tracheophyta' taxon_phylum, 'Liliopsida' taxon_class, 'Poales' taxon_order, 'Poaceae' taxon_family, 'Stipa' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); muy frecuente en la Región' murcia_status, 'Ficha básica: especie estructural del matorral semiárido, muy frecuente en la Región de Murcia y en los espartales de la Marina de Cope. Presencia en el parque muy probable; pendiente de confirmación puntual y de ampliar la ficha.' review_note
    UNION ALL
    SELECT 'Albaida' common_name, 'Anthyllis cytisoides' scientific_name, 'flora' kingdom, 'Leguminosa arbustiva' family, 'Matorral termomediterráneo semiárido' primary_habitat, 'No amenazada' conservation_status, 'Mata leguminosa blanco-tomentosa de flores amarillas en espiga, muy extendida en el matorral semiárido y los ribazos margosos del sureste; forma los albaidales.' description, NULL identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Anthyllis_cytisoides.JPG' image_url, 37.50110 latitude, -1.44940 longitude, 1 rarity_score, FALSE is_featured, 'Especie característica del hábitat 5330 (matorral termomediterráneo semiárido) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; muy extendida por la Región de Murcia (ficha de flora de regmurcia.com y Región de Murcia Digital). Ficha básica (mínima), pendiente de ampliar.' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Fabales' taxon_order, 'Fabaceae' taxon_family, 'Anthyllis' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); muy extendida por la Región' murcia_status, 'Ficha básica: especie característica del matorral semiárido, muy extendida por la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.' review_note
